17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
33	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.service.ClinicService;
39	import org.springframework.security.access.prepost.PreAuthorize;
40	import org.springframework.web.bind.annotation.CrossOrigin;
41	import org.springframework.web.bind.annotation.RequestMapping;
42	import org.springframework.web.bind.annotation.RestController;
43	import org.springframework.web.server.ResponseStatusException;
44	import org.springframework.web.util.UriComponentsBuilder;
45	
46	import jakarta.transaction.Transactional;
47	
48	/**
49	 * @author Vitaliy Fedoriv
50	 */
51	
52	@RestController
53	@CrossOrigin(exposedHeaders = "errors, content-type")
54	@RequestMapping("/api")
55	public class OwnerRestControllerV1 implements OwnersApi {
56	
57	    private final ClinicService clinicService;
58	
59	    private final OwnerMapper ownerMapper;
60	
61	    private final PetMapper petMapper;
62	
63	    private final VisitMapper visitMapper;
64	
65	    public OwnerRestControllerV1(ClinicService clinicService,
66	                                 OwnerMapper ownerMapper,
67	                                 PetMapper petMapper,
68	                                 VisitMapper visitMapper) {
69	        this.clinicService = clinicService;
70	        this.ownerMapper = ownerMapper;
71	        this.petMapper = petMapper;
72	        this.visitMapper = visitMapper;
73	    }
74	
75	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
76	    @Override
77	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
78	        Collection<Owner> owners;
79	        if (lastName != null) {
80	            owners = this.clinicService.findOwnerByLastName(lastName);
81	        } else {
82	            owners = this.clinicService.findAllOwners();
83	        }
84	        if (owners.isEmpty()) {
85	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
86	        }
87	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
93	        Owner owner = this.clinicService.findOwnerById(ownerId);
94	        if (owner == null) {
95	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
96	        }
97	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
103	        HttpHeaders headers = new HttpHeaders();
104	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
105	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
106	        owner.setTelephone(normalizedTelephone);
107	        owner.setEmail(normalizeEmail(owner.getEmail()));
108	        if (owner.getRegistrationDate() == null) {
109	            owner.setRegistrationDate(java.time.LocalDate.now());
110	        }
111	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
112	            .map(Owner::getTelephone)
113	            .filter(java.util.Objects::nonNull)
114	            .anyMatch(normalizedTelephone::equals);
115	        if (telephoneInUse) {
116	            throw new ResponseStatusException(HttpStatus.CONFLICT,
117	                "An owner with this telephone number already exists");
118	        }
119	        String lastNameKey = normalizeForHousehold(owner.getLastName());
120	        String addressKey = normalizeForHousehold(owner.getAddress());
121	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
122	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(lastNameKey)
123	                && normalizeForHousehold(existing.getAddress()).equals(addressKey))
124	            .toList();
125	        if (!householdMembers.isEmpty()) {
126	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
127	                throw new ResponseStatusException(HttpStatus.CONFLICT,
128	                    "An owner with this last name already exists at this address");
129	            }
130	            String householdId = householdId(lastNameKey, addressKey);
131	            owner.setHouseholdId(householdId);
132	            for (Owner member : householdMembers) {
133	                if (!householdId.equals(member.getHouseholdId())) {
134	                    member.setHouseholdId(householdId);
135	                    this.clinicService.saveOwner(member);
136	                }
137	            }
138	        }
139	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
140	        this.clinicService.saveOwner(owner);
141	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
142	        headers.setLocation(UriComponentsBuilder.newInstance()
143	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
144	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
145	    }
146	
147	    /**
148	     * Builds the customer code for a new owner, formatted {@code '<LAST3>-<NNNN>'} where
149	     * {@code LAST3} is the upper-cased first three letters of the last name and {@code NNNN}
150	     * is a global 4-digit zero-padded sequence equal to one more than the current number of
151	     * owners (e.g. {@code 'SMI-0007'}).
152	     *
153	     * @param lastName the owner's last name
154	     * @return the assigned customer code
155	     */
156	    private String nextCustomerCode(String lastName) {
157	        String prefix = (lastName == null ? "" : lastName);
158	        prefix = prefix.substring(0, Math.min(3, prefix.length())).toUpperCase(java.util.Locale.ROOT);
159	        long sequence = this.clinicService.findAllOwners().size() + 1L;
160	        return String.format("%s-%04d", prefix, sequence);
161	    }
162	
163	    /**
164	     * Normalizes a value for household-duplicate comparison: leading and trailing whitespace is
165	     * trimmed, any internal run of whitespace is collapsed to a single space, and the result is
166	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to the
167	     * empty string.
168	     *
169	     * @param value the raw value (last name or address) as submitted
170	     * @return the normalized comparison key
171	     */
172	    private String normalizeForHousehold(String value) {
173	        if (value == null) {
174	            return "";
175	        }
176	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
177	    }
178	
179	    /**
180	     * Derives the stable shared household identifier for a household, keyed on the normalized last
181	     * name and address. Because it is a pure function of those normalized keys, every owner in the
182	     * same household deterministically computes the same value. The identifier is the first 12
183	     * upper-case hex characters of the SHA-256 digest of the two keys joined with a NUL separator
184	     * (the separator prevents distinct name/address pairs from colliding).
185	     *
186	     * @param lastNameKey the normalized last-name comparison key
187	     * @param addressKey  the normalized address comparison key
188	     * @return the stable household identifier
189	     */
190	    private String householdId(String lastNameKey, String addressKey) {
191	        String seed = lastNameKey + "�" + addressKey;
192	        try {
193	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
194	                .digest(seed.getBytes(java.nio.charset.StandardCharsets.UTF_8));
195	            StringBuilder sb = new StringBuilder(digest.length * 2);
196	            for (byte b : digest) {
197	                sb.append(String.format("%02x", b));
198	            }
199	            return sb.substring(0, 12).toUpperCase(java.util.Locale.ROOT);
200	        }
201	        catch (java.security.NoSuchAlgorithmException e) {
202	            throw new IllegalStateException("SHA-256 not available", e);
203	        }
204	    }
205	
206	    /**
207	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets (indeed any
208	     * non-digit character) are stripped. If the submitted value carries a leading {@code '+'}
209	     * its country code is kept as-is; otherwise the default country code {@code '+61'} is
210	     * assumed and a single leading {@code '0'} is dropped from the national digits. The
211	     * resulting value must be a {@code '+'} followed by 8 to 15 digits. So {@code '0412 345 678'}
212	     * is stored as {@code '+61412345678'}.
213	     *
214	     * @param telephone the raw telephone number as submitted
215	     * @return the normalized E.164 telephone number
216	     * @throws ResponseStatusException with a 400 status if the value cannot form a valid E.164
217	     *         number (8 to 15 digits after the '+')
218	     */
219	    private String normalizeTelephone(String telephone) {
220	        String raw = telephone == null ? "" : telephone.trim();
221	        String digits = raw.replaceAll("\\D", "");
222	        String e164;
223	        if (raw.startsWith("+")) {
224	            e164 = "+" + digits;
225	        } else {
226	            if (digits.startsWith("0")) {
227	                digits = digits.substring(1);
228	            }
229	            e164 = "+61" + digits;
230	        }
231	        int digitCount = e164.length() - 1;
232	        if (digitCount < 8 || digitCount > 15) {
233	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
234	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
235	        }
236	        return e164;
237	    }
238	
239	    /**
240	     * Normalizes an optional email address by lower-casing it. Syntactic validity is enforced
241	     * by Bean Validation on the request DTO, so a value reaching this point is either {@code null}
242	     * (absent) or already valid.
243	     *
244	     * @param email the email address as submitted, or {@code null} when absent
245	     * @return the lower-cased email, or {@code null} when absent
246	     */
247	    private String normalizeEmail(String email) {
248	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
249	    }
250	
251	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
252	    @Override
253	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
254	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
255	        if (currentOwner == null) {
256	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
257	        }
258	        currentOwner.setAddress(ownerFieldsDto.getAddress());
259	        currentOwner.setCity(ownerFieldsDto.getCity());
260	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
261	        currentOwner.setLastName(ownerFieldsDto.getLastName());
262	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
263	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
264	        this.clinicService.saveOwner(currentOwner);
265	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
266	    }
267	
268	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
269	    @Transactional
270	    @Override
271	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
272	        Owner owner = this.clinicService.findOwnerById(ownerId);
273	        if (owner == null) {
274	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
275	        }
276	        this.clinicService.deleteOwner(owner);
277	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
278	    }
279	
280	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
281	    @Override
282	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
283	        Owner owner = this.clinicService.findOwnerById(ownerId);
284	        if (owner == null) {
285	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
286	        }
287	        HttpHeaders headers = new HttpHeaders();
288	        Pet pet = petMapper.toPet(petFieldsDto);
289	        owner.setId(ownerId);
290	        pet.setOwner(owner);
291	        pet.getType().setName(null);
292	        this.clinicService.savePet(pet);
293	        PetDto petDto = petMapper.toPetDto(pet);
